<?php
declare(strict_types=1);

function operations_module_loaded(): bool { return true; }
function operations_enabled(): bool { return setting_bool('commercial_operations_enabled', true); }
function operations_row(string $sql,array $p=[]): ?array { try{$q=db()->prepare($sql);$q->execute($p);return $q->fetch()?:null;}catch(Throwable $e){runtime_log('Operations row failed',$e);return null;} }
function operations_rows(string $sql,array $p=[]): array { try{$q=db()->prepare($sql);$q->execute($p);return $q->fetchAll()?:[];}catch(Throwable $e){runtime_log('Operations rows failed',$e);return [];} }
function operations_scalar(string $sql,array $p=[],$default=0){try{$q=db()->prepare($sql);$q->execute($p);$v=$q->fetchColumn();return $v===false?$default:$v;}catch(Throwable $e){return $default;}}
function operations_ref(string $prefix): string { return strtoupper($prefix).'-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(4))); }
function operations_json($v): string { try{return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?:'{}';}catch(Throwable $e){return '{}';} }
function operations_audit(string $action,string $entityType='',?int $entityId=null,$old=null,$new=null,?int $userId=null): void {
    if(!operations_enabled())return; $u=$userId?:((current_user()['id']??null)?(int)current_user()['id']:null);
    try{db()->prepare('INSERT INTO audit_logs(user_id,action,entity_type,entity_id,old_json,new_json,ip_address,user_agent) VALUES(?,?,?,?,?,?,?,?)')->execute([$u,$action,$entityType?:null,$entityId,$old===null?null:operations_json($old),$new===null?null:operations_json($new),function_exists('activity_client_ip')?activity_client_ip():substr((string)($_SERVER['REMOTE_ADDR']??''),0,64),substr((string)($_SERVER['HTTP_USER_AGENT']??''),0,500)]);}catch(Throwable $e){}
    if(function_exists('activity_log_event'))activity_log_event($action,'audit',$entityType,$entityId,['old'=>$old,'new'=>$new],$u,'admin');
}

function seller_wallet(int $sellerId,bool $lock=false): array {
    db()->prepare('INSERT IGNORE INTO seller_wallets(seller_user_id) VALUES(?)')->execute([$sellerId]);
    $sql='SELECT * FROM seller_wallets WHERE seller_user_id=?'.($lock?' FOR UPDATE':'');$q=db()->prepare($sql);$q->execute([$sellerId]);return $q->fetch()?:['seller_user_id'=>$sellerId,'available_balance'=>0,'pending_balance'=>0,'lifetime_earnings'=>0,'lifetime_paid_out'=>0];
}
function seller_wallet_tx(int $sellerId,string $type,float $amount,string $refType='',?int $refId=null,string $description='',?int $by=null): int {
    $amount=round(abs($amount),2); if($amount<=0)return 0; $w=seller_wallet($sellerId,true); $balance=(float)$w['available_balance'];
    $credit=in_array($type,['sale_credit','adjustment_credit'],true); $new=round($balance+($credit?$amount:-$amount),2);
    if($new<0 && $type!=='refund_debit') throw new RuntimeException('Seller wallet has insufficient available balance.');
    $earn=(float)$w['lifetime_earnings']+($type==='sale_credit'?$amount:0);$paid=(float)$w['lifetime_paid_out']+($type==='payout_debit'?$amount:0);
    db()->prepare('UPDATE seller_wallets SET available_balance=?,lifetime_earnings=?,lifetime_paid_out=? WHERE seller_user_id=?')->execute([$new,$earn,$paid,$sellerId]);
    db()->prepare('INSERT INTO seller_wallet_transactions(seller_user_id,transaction_type,amount,balance_after,reference_type,reference_id,description,created_by) VALUES(?,?,?,?,?,?,?,?)')->execute([$sellerId,$type,$amount,$new,$refType?:null,$refId,$description?:null,$by]);
    return (int)db()->lastInsertId();
}
function operations_commission_for_order(array $order): array {
    $seller=(int)$order['seller_user_id'];
    $item=operations_row('SELECT oi.product_type,p.category_id,p.sale_mode FROM store_order_items oi JOIN store_products p ON p.id=oi.product_id WHERE oi.order_id=? ORDER BY oi.id LIMIT 1',[(int)$order['id']])?:[];
    $type=(string)($item['product_type']??'all');if(($item['sale_mode']??'')==='auction')$type='auction';
    $gross=(float)$order['grand_total'];
    if(function_exists('v41_resolve_commission')&&setting_bool('monetization_commission_enabled',true)){
        $plan=function_exists('growth_user_active_plan')?growth_user_active_plan($seller):null;
        $r=v41_resolve_commission(['product_type'=>$type,'category_id'=>(int)($item['category_id']??0),'seller_user_id'=>$seller,'plan_id'=>(int)($plan['id']??0)]);
        if(($r['name']??'')!=='Platform default'||v41_table_exists('monetization_commission_rules')){
            $fee=($gross*(float)($r['percent_rate']??0)/100)+(float)($r['flat_fee']??0);$fee=max(0,min($gross,round($fee,2)));return ['gross'=>$gross,'commission'=>$fee,'seller'=>round($gross-$fee,2),'rule'=>$r];
        }
    }
    $rule=operations_row("SELECT * FROM commission_rules WHERE status=1 AND (seller_user_id=? OR seller_user_id IS NULL) AND (product_type=? OR product_type='all') ORDER BY (seller_user_id IS NOT NULL) DESC,(product_type<>'all') DESC,priority ASC,id ASC LIMIT 1",[$seller,$type]);
    $value=(float)($rule['commission_value']??setting('marketplace_default_commission_percent','10'));$kind=(string)($rule['commission_type']??'percent');
    $fee=$kind==='fixed'?$value:($gross*$value/100);$fee=max(0,min($gross,round($fee,2)));return ['gross'=>$gross,'commission'=>$fee,'seller'=>round($gross-$fee,2),'rule'=>$rule];
}

function operations_ensure_invoice(int $orderId): ?array {
    $existing=operations_row('SELECT * FROM commerce_invoices WHERE order_id=? LIMIT 1',[$orderId]); if($existing)return $existing;
    $o=operations_row('SELECT * FROM store_orders WHERE id=? LIMIT 1',[$orderId]);if(!$o)return null;
    $number=operations_ref('INV');$paid=$o['payment_status']==='paid'?(float)$o['grand_total']:0.0;$status=$paid>0?'paid':'issued';
    db()->prepare('INSERT INTO commerce_invoices(invoice_number,order_id,payment_order_id,buyer_user_id,seller_user_id,issue_date,due_date,subtotal,shipping_amount,discount_amount,tax_amount,total_amount,paid_amount,status,billing_name,billing_phone,billing_email,billing_address,notes) VALUES(?,?,?,?,?,CURDATE(),CURDATE(),?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$number,$orderId,$o['payment_order_id']?:null,$o['buyer_user_id'],$o['seller_user_id'],$o['subtotal'],$o['shipping_total'],0,0,$o['grand_total'],$paid,$status,$o['customer_name'],$o['customer_phone'],$o['customer_email'],$o['shipping_address'],'Marketplace order '.$o['order_number']]);
    $invoiceId=(int)db()->lastInsertId();$items=operations_rows('SELECT * FROM store_order_items WHERE order_id=? ORDER BY id',[$orderId]);$ins=db()->prepare('INSERT INTO commerce_invoice_items(invoice_id,description,quantity,unit_price,line_total,product_id) VALUES(?,?,?,?,?,?)');foreach($items as $i)$ins->execute([$invoiceId,$i['title'],$i['quantity'],$i['unit_price'],$i['line_total'],$i['product_id']]);
    operations_audit('invoice.created','commerce_invoice',$invoiceId,null,['order_id'=>$orderId]);return operations_row('SELECT * FROM commerce_invoices WHERE id=?',[$invoiceId]);
}
function operations_sync_invoice(int $orderId): void {
    $i=operations_ensure_invoice($orderId);$o=operations_row('SELECT * FROM store_orders WHERE id=?',[$orderId]);if(!$i||!$o)return;$paid=$o['payment_status']==='paid'?(float)$o['grand_total']:0;$status=$o['payment_status']==='refunded'?'refunded':($paid>0?'paid':'issued');db()->prepare('UPDATE commerce_invoices SET payment_order_id=?,paid_amount=?,status=? WHERE id=?')->execute([$o['payment_order_id']?:null,$paid,$status,$i['id']]);
}
function operations_settle_order(int $orderId,?int $by=null): bool {
    $o=operations_row('SELECT * FROM store_orders WHERE id=?',[$orderId]);if(!$o||$o['payment_status']!=='paid'||!in_array($o['status'],['delivered','completed'],true))return false;
    if(operations_row("SELECT * FROM commerce_order_settlements WHERE order_id=? AND status='settled'",[$orderId]))return true;$calc=operations_commission_for_order($o);
    db()->beginTransaction();try{
        $old=operations_row('SELECT * FROM commerce_order_settlements WHERE order_id=? FOR UPDATE',[$orderId]);if($old&&$old['status']==='settled'){db()->commit();return true;}
        if($old)db()->prepare("UPDATE commerce_order_settlements SET gross_amount=?,commission_amount=?,seller_amount=?,status='settled',settled_at=NOW(),reversed_at=NULL WHERE id=?")->execute([$calc['gross'],$calc['commission'],$calc['seller'],$old['id']]);else db()->prepare("INSERT INTO commerce_order_settlements(order_id,seller_user_id,gross_amount,commission_amount,seller_amount,status,settled_at) VALUES(?,?,?,?,?,'settled',NOW())")->execute([$orderId,$o['seller_user_id'],$calc['gross'],$calc['commission'],$calc['seller']]);
        seller_wallet_tx((int)$o['seller_user_id'],'sale_credit',(float)$calc['seller'],'order',$orderId,'Marketplace settlement '.$o['order_number'],$by);
        try{if(function_exists('accounting_post_journal'))accounting_post_journal('Marketplace settlement '.$o['order_number'],[['account_id'=>accounting_account_id('store_revenue'),'debit'=>$calc['gross'],'memo'=>'Reclassify gross marketplace revenue'],['account_id'=>accounting_account_id('marketplace_commission'),'credit'=>$calc['commission'],'memo'=>'Platform commission'],['account_id'=>accounting_account_id('seller_payable'),'credit'=>$calc['seller'],'user_id'=>$o['seller_user_id'],'memo'=>'Seller payable']],'marketplace_settlement',$orderId,$by);}catch(Throwable $e){runtime_log('Settlement accounting skipped',$e);}
        db()->commit();operations_audit('order.settled','store_order',$orderId,null,$calc,$by);return true;
    }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
function operations_after_payment_paid(array $paymentOrder,?int $by=null): void {
    try{$meta=json_decode((string)($paymentOrder['metadata_json']??'{}'),true);$orderId=(int)($meta['store_order_id']??0);if(!$orderId&&!empty($paymentOrder['id']))$orderId=(int)operations_scalar('SELECT id FROM store_orders WHERE payment_order_id=? LIMIT 1',[(int)$paymentOrder['id']],0);if($orderId){operations_sync_invoice($orderId);$o=operations_row('SELECT status FROM store_orders WHERE id=?',[$orderId]);if($o&&in_array($o['status'],['delivered','completed'],true))operations_settle_order($orderId,$by);}}catch(Throwable $e){runtime_log('Operations paid hook failed',$e);}
}
function operations_set_order_status(int $orderId,string $status,?int $by=null,?int $sellerId=null): void {
    $allowed=['pending','confirmed','processing','shipped','delivered','completed','cancelled'];if(!in_array($status,$allowed,true))throw new RuntimeException('Invalid order status.');$o=operations_row('SELECT * FROM store_orders WHERE id=?',[$orderId]);if(!$o)throw new RuntimeException('Order not found.');if($sellerId!==null&&(int)$o['seller_user_id']!==$sellerId)throw new RuntimeException('Order not found.');
    if($status==='cancelled'){if($o['payment_status']==='paid')throw new RuntimeException('Paid orders require the refund/dispute workflow before cancellation.');store_cancel_order($orderId);}else db()->prepare('UPDATE store_orders SET status=? WHERE id=?')->execute([$status,$orderId]);
    operations_sync_invoice($orderId);if(in_array($status,['shipped','delivered'],true))operations_ensure_shipment($orderId,$status==='delivered'?'delivered':'dispatched',$by);if(in_array($status,['delivered','completed'],true))operations_settle_order($orderId,$by);operations_audit('order.status','store_order',$orderId,['status'=>$o['status']],['status'=>$status],$by);
}

function seller_request_payout(int $sellerId,float $amount,string $method,string $account): array {
    $amount=round($amount,2);$min=(float)setting('seller_min_payout','1000');$fee=max(0,round((float)setting('seller_payout_fee','0'),2));$allowedMethods=['bank','jazzcash','easypaisa'];
    if($amount<$min)throw new RuntimeException('Minimum payout is Rs '.number_format($min,0).'.');if($fee>=$amount)throw new RuntimeException('Payout amount must be greater than the payout fee.');if(!in_array($method,$allowedMethods,true))throw new RuntimeException('Invalid payout method.');if(trim($account)==='')throw new RuntimeException('Payout account is required.');
