function operations_update_payout(int $id,string $status,?int $by=null,string $reference='',string $notes=''): void {
    $allowed=['requested','approved','processing','paid','rejected','cancelled'];if(!in_array($status,$allowed,true))throw new RuntimeException('Invalid payout status.');
