        db()->prepare('UPDATE seller_payout_requests SET status=?,gateway_reference=?,notes=?,processed_by=?,processed_at=IF(? IN (\'paid\',\'rejected\',\'cancelled\'),NOW(),processed_at) WHERE id=?')->execute([$status,$reference?:null,$notes?:null,$by,$status,$id]);db()->commit();operations_audit('payout.status','seller_payout',$id,['status'=>$current],['status'=>$status,'reference'=>$reference],$by);
    }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}

function support_create_ticket(int $userId,string $subject,string $message,string $department='general',string $priority='normal',?int $orderId=null,?int $businessId=null): array {
