function support_reply(int $ticketId,int $userId,string $message,bool $staff=false,bool $internal=false,?string $status=null): void {$message=trim($message);if($message==='')throw new RuntimeException('Reply cannot be empty.');$t=operations_row('SELECT * FROM support_tickets WHERE id=?',[$ticketId]);if(!$t)throw new RuntimeException('Ticket not found.');db()->prepare('INSERT INTO support_messages(ticket_id,user_id,message,is_staff,is_internal) VALUES(?,?,?,?,?)')->execute([$ticketId,$userId,$message,$staff?1:0,$internal?1:0]);$allowed=['open','in_progress','waiting_customer','resolved','closed'];$new=$status&&in_array($status,$allowed,true)?$status:($staff?'waiting_customer':'open');db()->prepare('UPDATE support_tickets SET status=?,last_message_at=NOW() WHERE id=?')->execute([$new,$ticketId]);operations_audit('support.reply','support_ticket',$ticketId,null,['staff'=>$staff,'status'=>$new],$userId);}

function operations_open_dispute(int $orderId,int $userId,string $reason,string $description,float $amount=0): array {
