function inventory_default_location(int $sellerId): int {$id=(int)operations_scalar('SELECT id FROM inventory_locations WHERE seller_user_id=? AND status=1 ORDER BY id LIMIT 1',[$sellerId],0);if($id)return $id;db()->prepare("INSERT INTO inventory_locations(seller_user_id,name,location_type,status) VALUES(?,'Main Stock','shop',1)")->execute([$sellerId]);return (int)db()->lastInsertId();}
function inventory_move(int $sellerId,int $productId,int $qty,string $type,?int $variantId=null,?int $locationId=null,string $refType='',?int $refId=null,string $note='',?int $by=null): void {
    if($qty<=0)throw new RuntimeException('Quantity must be greater than zero.');$in=in_array($type,['opening','purchase','return_in','adjustment_in'],true);$delta=$in?$qty:-$qty;$own=!db()->inTransaction();if($own)db()->beginTransaction();try{$p=operations_row('SELECT * FROM store_products WHERE id=? FOR UPDATE',[$productId]);if(!$p||(int)$p['seller_user_id']!==$sellerId)throw new RuntimeException('Product not found.');$new=(int)$p['stock']+$delta;if($new<0)throw new RuntimeException('Insufficient stock.');db()->prepare("UPDATE store_products SET stock=?,status=IF(?<=0,'soldout',IF(status='soldout','published',status)) WHERE id=?")->execute([$new,$new,$productId]);if($variantId){$v=operations_row('SELECT * FROM product_variants WHERE id=? AND product_id=? FOR UPDATE',[$variantId,$productId]);if(!$v)throw new RuntimeException('Variant not found.');$vn=(int)$v['stock_qty']+$delta;if($vn<0)throw new RuntimeException('Insufficient variant stock.');db()->prepare('UPDATE product_variants SET stock_qty=? WHERE id=?')->execute([$vn,$variantId]);}$locationId=$locationId?:inventory_default_location($sellerId);db()->prepare('INSERT INTO inventory_movements(seller_user_id,product_id,variant_id,location_id,movement_type,quantity,reference_type,reference_id,note,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$sellerId,$productId,$variantId,$locationId,$type,$delta,$refType?:null,$refId,$note?:null,$by]);if($own)db()->commit();operations_audit('inventory.movement','store_product',$productId,null,['type'=>$type,'qty'=>$delta],$by);}catch(Throwable $e){if($own&&db()->inTransaction())db()->rollBack();throw $e;}
}
function inventory_save_variant(int $sellerId,int $productId,string $name,string $sku='',string $barcode='',float $priceAdjustment=0,?int $id=null): int {$p=operations_row('SELECT id FROM store_products WHERE id=? AND seller_user_id=?',[$productId,$sellerId]);if(!$p)throw new RuntimeException('Product not found.');if(trim($name)==='')throw new RuntimeException('Variant name is required.');if($id){db()->prepare('UPDATE product_variants SET variant_name=?,sku=?,barcode=?,price_adjustment=? WHERE id=? AND product_id=?')->execute([trim($name),trim($sku)?:null,trim($barcode)?:null,$priceAdjustment,$id,$productId]);return $id;}db()->prepare('INSERT INTO product_variants(product_id,variant_name,sku,barcode,price_adjustment,stock_qty,status) VALUES(?,?,?,?,?,0,1)')->execute([$productId,trim($name),trim($sku)?:null,trim($barcode)?:null,$priceAdjustment]);return (int)db()->lastInsertId();}

function purchasing_receive(int $poId,?int $by=null): void {
    $po=operations_row('SELECT * FROM purchase_orders WHERE id=?',[$poId]);if(!$po)throw new RuntimeException('Purchase order not found.');$items=operations_rows('SELECT * FROM purchase_order_items WHERE purchase_order_id=?',[$poId]);if(!$items)throw new RuntimeException('Purchase order has no items.');
    db()->beginTransaction();try{foreach($items as $i){$remaining=(int)$i['quantity']-(int)$i['received_qty'];if($remaining<=0)continue;$p=operations_row('SELECT seller_user_id FROM store_products WHERE id=?',[$i['product_id']]);if(!$p)continue;inventory_move((int)$p['seller_user_id'],(int)$i['product_id'],$remaining,'purchase',$i['variant_id']? (int)$i['variant_id']:null,null,'purchase_order',$poId,'PO '.$po['po_number'],$by);db()->prepare('UPDATE purchase_order_items SET received_qty=quantity WHERE id=?')->execute([$i['id']]);}db()->prepare("UPDATE purchase_orders SET status='received' WHERE id=?")->execute([$poId]);try{if(function_exists('accounting_post_journal')&&(float)$po['total_amount']>0)accounting_post_journal('Purchase order received '.$po['po_number'],[['account_id'=>accounting_account_id('inventory_asset'),'debit'=>$po['total_amount']],['account_id'=>accounting_account_id('vendor_payable'),'credit'=>$po['total_amount']]],'purchase_order',$poId,$by);}catch(Throwable $e){runtime_log('Purchase accounting skipped',$e);}db()->commit();operations_audit('purchase.received','purchase_order',$poId,null,['total'=>$po['total_amount']],$by);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
function payment_webhook_rotate(string $gateway): string {$gateway=preg_replace('/[^a-z0-9_-]/i','',strtolower($gateway))?:'generic';$token=bin2hex(random_bytes(24));$hash=password_hash($token,PASSWORD_DEFAULT);db()->prepare('INSERT INTO payment_gateway_webhook_keys(gateway_slug,token_hash,status,rotated_at) VALUES(?,?,1,NOW()) ON DUPLICATE KEY UPDATE token_hash=VALUES(token_hash),status=1,rotated_at=NOW()')->execute([$gateway,$hash]);operations_audit('webhook.rotated','payment_gateway',null,null,['gateway'=>$gateway]);return $token;}
function payment_webhook_verify(string $gateway,string $token): bool {$r=operations_row('SELECT * FROM payment_gateway_webhook_keys WHERE gateway_slug=? AND status=1',[$gateway]);if(!$r||$token==='')return false;$ok=password_verify($token,(string)$r['token_hash']);if($ok)db()->prepare('UPDATE payment_gateway_webhook_keys SET last_used_at=NOW() WHERE id=?')->execute([$r['id']]);return $ok;}
function payment_webhook_process(string $gateway,array $payload,array $headers=[]): array {
    $event=(string)($payload['event_id']??$payload['id']??'');$ref=(string)($payload['reference']??$payload['payment_reference']??'');$paymentId=(int)($payload['payment_order_id']??0);$status=strtolower((string)($payload['status']??''));$amount=(float)($payload['amount']??0);$logId=0;
    try{db()->prepare('INSERT INTO payment_webhook_logs(gateway_slug,event_id,payload_json,headers_json,status) VALUES(?,?,?,?,\'received\')')->execute([$gateway,$event?:null,operations_json($payload),operations_json($headers)]);$logId=(int)db()->lastInsertId();}catch(Throwable $e){if($event){$old=operations_row('SELECT * FROM payment_webhook_logs WHERE gateway_slug=? AND event_id=?',[$gateway,$event]);if($old&&$old['status']==='processed')return ['ok'=>true,'duplicate'=>true];}}
    try{if(!$paymentId&&$ref)$paymentId=(int)operations_scalar('SELECT id FROM payment_orders WHERE reference=? OR gateway_reference=? LIMIT 1',[$ref,$ref],0);if(!$paymentId)throw new RuntimeException('Payment order could not be resolved.');$o=operations_row('SELECT * FROM payment_orders WHERE id=?',[$paymentId]);if(!$o)throw new RuntimeException('Payment order not found.');
        if(in_array($status,['paid','success','completed'],true)){if($amount>0&&abs($amount-(float)$o['amount'])>0.01)throw new RuntimeException('Webhook amount does not match payment order.');if($o['status']!=='paid')mark_payment_order_paid($paymentId,$gateway,$ref?:('WH-'.$paymentId),['webhook'=>true,'payload'=>$payload],null);}
        if($logId)db()->prepare("UPDATE payment_webhook_logs SET status='processed',message=?,processed_at=NOW() WHERE id=?")->execute(['Processed payment '.$paymentId,$logId]);operations_audit('payment.webhook','payment_order',$paymentId,null,['gateway'=>$gateway,'status'=>$status]);return ['ok'=>true,'payment_order_id'=>$paymentId];
    }catch(Throwable $e){if($logId)db()->prepare("UPDATE payment_webhook_logs SET status='failed',message=?,processed_at=NOW() WHERE id=?")->execute([substr($e->getMessage(),0,700),$logId]);throw $e;}
}
function payment_reconcile(int $paymentOrderId,float $received,string $gateway='',string $reference='',?int $by=null,string $notes=''): string {$o=operations_row('SELECT * FROM payment_orders WHERE id=?',[$paymentOrderId]);if(!$o)throw new RuntimeException('Payment order not found.');$expected=(float)$o['amount'];$status=abs($expected-$received)<0.01?'matched':($received<$expected?'underpaid':'overpaid');db()->prepare('INSERT INTO payment_reconciliation(payment_order_id,expected_amount,received_amount,gateway,gateway_reference,status,reconciled_by,reconciled_at,notes) VALUES(?,?,?,?,?,?,?,NOW(),?) ON DUPLICATE KEY UPDATE received_amount=VALUES(received_amount),gateway=VALUES(gateway),gateway_reference=VALUES(gateway_reference),status=VALUES(status),reconciled_by=VALUES(reconciled_by),reconciled_at=NOW(),notes=VALUES(notes)')->execute([$paymentOrderId,$expected,$received,$gateway?:null,$reference?:null,$status,$by,$notes?:null]);operations_audit('payment.reconciled','payment_order',$paymentOrderId,null,['status'=>$status,'received'=>$received],$by);return $status;}

function operations_enqueue(string $jobType,array $payload=[],string $queue='default',?string $availableAt=null,int $maxAttempts=3): int {$availableAt=$availableAt?:date('Y-m-d H:i:s');db()->prepare("INSERT INTO job_queue(queue_name,job_type,payload_json,status,attempts,max_attempts,available_at) VALUES(?,?,?,'pending',0,?,?)")->execute([$queue,$jobType,operations_json($payload),max(1,$maxAttempts),$availableAt]);return (int)db()->lastInsertId();}
function operations_run_job(array $job): void {$payload=json_decode((string)($job['payload_json']??'{}'),true)?:[];switch((string)$job['job_type']){case 'health_snapshot':operations_health_snapshot();break;case 'settle_order':operations_settle_order((int)($payload['order_id']??0));break;case 'create_invoice':operations_ensure_invoice((int)($payload['order_id']??0));break;case 'cleanup_jobs':db()->exec("DELETE FROM job_queue WHERE status='completed' AND completed_at<DATE_SUB(NOW(),INTERVAL 30 DAY)");break;default:throw new RuntimeException('Unknown job type: '.$job['job_type']);}}
function operations_run_queue(int $limit=10): array {$limit=max(1,min(100,$limit));$worker='web-'.substr(bin2hex(random_bytes(6)),0,12);$done=0;$failed=0;for($n=0;$n<$limit;$n++){db()->beginTransaction();try{$j=operations_row("SELECT * FROM job_queue WHERE status='pending' AND available_at<=NOW() AND attempts<max_attempts ORDER BY id ASC LIMIT 1 FOR UPDATE");if(!$j){db()->commit();break;}db()->prepare("UPDATE job_queue SET status='processing',attempts=attempts+1,locked_at=NOW(),locked_by=? WHERE id=?")->execute([$worker,$j['id']]);db()->commit();try{operations_run_job($j);db()->prepare("UPDATE job_queue SET status='completed',completed_at=NOW(),locked_at=NULL,locked_by=NULL WHERE id=?")->execute([$j['id']]);$done++;}catch(Throwable $e){$attempt=(int)$j['attempts']+1;$status=$attempt>=(int)$j['max_attempts']?'failed':'pending';db()->prepare('UPDATE job_queue SET status=?,last_error=?,available_at=DATE_ADD(NOW(),INTERVAL 5 MINUTE),locked_at=NULL,locked_by=NULL WHERE id=?')->execute([$status,substr($e->getMessage(),0,2000),$j['id']]);$failed++;}}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$failed++;break;}}return ['completed'=>$done,'failed'=>$failed];}

function operations_health_snapshot(): array {$checks=[];$add=function(string $type,string $status,string $value)use(&$checks){$checks[]=[$type,$status,$value];try{db()->prepare('INSERT INTO health_checks(check_type,status,value_text,meta_json) VALUES(?,?,?,?)')->execute([$type,$status,substr($value,0,700),null]);}catch(Throwable $e){}};$add('database','ok','Database connected');$free=@disk_free_space(__DIR__.'/../storage');$total=@disk_total_space(__DIR__.'/../storage');if($free!==false&&$total){$pct=($free/$total)*100;$add('disk',$pct<10?'critical':($pct<20?'warning':'ok'),number_format($pct,1).'% free');}$pending=(int)operations_scalar("SELECT COUNT(*) FROM job_queue WHERE status='pending'",[],0);$failed=(int)operations_scalar("SELECT COUNT(*) FROM job_queue WHERE status='failed'",[],0);$add('queue',$failed>10?'warning':'ok',$pending.' pending / '.$failed.' failed');$log=__DIR__.'/../storage/logs/runtime-errors.log';$size=is_file($log)?filesize($log):0;$add('runtime_log',$size>5*1024*1024?'warning':'ok',number_format($size/1024,1).' KB');return $checks;}
function operations_backup_database(?int $by=null): array {
    $dir=__DIR__.'/../storage/backups';if(!is_dir($dir)&&!mkdir($dir,0750,true)&&!is_dir($dir))throw new RuntimeException('Cannot create backup directory.');@file_put_contents($dir.'/.htaccess',"Require all denied\nDeny from all\n");@file_put_contents($dir.'/index.html','');$name='shahkotpk-db-'.date('Ymd-His').'-'.bin2hex(random_bytes(5)).'.sql';$path=$dir.'/'.$name;db()->prepare("INSERT INTO backup_records(backup_type,file_name,status,created_by) VALUES('database',?,'running',?)")->execute([$name,$by]);$id=(int)db()->lastInsertId();
    try{$fh=fopen($path,'wb');if(!$fh)throw new RuntimeException('Cannot write backup file.');fwrite($fh,"-- ShahkotPK database backup ".date(DATE_ATOM)."\nSET FOREIGN_KEY_CHECKS=0;\n");$tables=db()->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);foreach($tables as $table){$safe=str_replace('`','``',(string)$table);$cr=db()->query("SHOW CREATE TABLE `{$safe}`")->fetch();if($cr)fwrite($fh,"\nDROP TABLE IF EXISTS `{$safe}`;\n".($cr['Create Table']??array_values($cr)[1]).";\n");$q=db()->query("SELECT * FROM `{$safe}`");while($row=$q->fetch(PDO::FETCH_ASSOC)){$cols=array_map(function($c){return '`'.str_replace('`','``',$c).'`';},array_keys($row));$vals=[];foreach($row as $v)$vals[]=$v===null?'NULL':db()->quote((string)$v);fwrite($fh,'INSERT INTO `'.$safe.'` ('.implode(',',$cols).') VALUES ('.implode(',',$vals).');' . "\n");}}fwrite($fh,"SET FOREIGN_KEY_CHECKS=1;\n");fclose($fh);$size=filesize($path)?:0;$hash=hash_file('sha256',$path)?:null;db()->prepare("UPDATE backup_records SET file_size=?,checksum_sha256=?,status='completed',completed_at=NOW() WHERE id=?")->execute([$size,$hash,$id]);operations_audit('backup.created','backup_record',$id,null,['file'=>$name,'size'=>$size],$by);return operations_row('SELECT * FROM backup_records WHERE id=?',[$id])?:[];}catch(Throwable $e){if(isset($fh)&&is_resource($fh))fclose($fh);db()->prepare("UPDATE backup_records SET status='failed',notes=?,completed_at=NOW() WHERE id=?")->execute([substr($e->getMessage(),0,700),$id]);throw $e;}
}
function operations_dashboard_stats(): array {return ['open_tickets'=>(int)operations_scalar("SELECT COUNT(*) FROM support_tickets WHERE status NOT IN ('resolved','closed')"),'open_disputes'=>(int)operations_scalar("SELECT COUNT(*) FROM commerce_disputes WHERE status IN ('open','reviewing','seller_response')"),'pending_payouts'=>(int)operations_scalar("SELECT COUNT(*) FROM seller_payout_requests WHERE status IN ('requested','approved','processing')"),'payout_amount'=>(float)operations_scalar("SELECT COALESCE(SUM(net_amount),0) FROM seller_payout_requests WHERE status IN ('requested','approved','processing')"),'shipments'=>(int)operations_scalar("SELECT COUNT(*) FROM shipments WHERE status NOT IN ('delivered','returned','failed')"),'unpaid_invoices'=>(int)operations_scalar("SELECT COUNT(*) FROM commerce_invoices WHERE status IN ('issued','partially_paid')"),'failed_jobs'=>(int)operations_scalar("SELECT COUNT(*) FROM job_queue WHERE status='failed'"),'vendors'=>(int)operations_scalar('SELECT COUNT(*) FROM vendors WHERE status=1')];}

function operations_cron_token(): string { $t=trim((string)setting('operations_cron_token','')); if($t===''){ $t=bin2hex(random_bytes(24)); try{save_setting('operations_cron_token',$t);}catch(Throwable $e){} } return $t; }

function inventory_log_only(int $sellerId,int $productId,int $signedQty,string $type,string $refType='',?int $refId=null,string $note='',?int $by=null): void {try{$location=inventory_default_location($sellerId);db()->prepare('INSERT INTO inventory_movements(seller_user_id,product_id,variant_id,location_id,movement_type,quantity,reference_type,reference_id,note,created_by) VALUES(?,?,NULL,?,?,?,?,?,?,?)')->execute([$sellerId,$productId,$location,$type,$signedQty,$refType?:null,$refId,$note?:null,$by]);}catch(Throwable $e){runtime_log('Inventory history log skipped',$e);}}
